<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref} from 'vue'
import {accountRequest} from '../accountAccess'
import {downloadFile} from '../downloadFile'
import DetailDialog from './DetailDialog.vue'
const props=defineProps<{base:string;token:string}>()
type Run={id:string;name:string;dataset_version:string;case_count:number;metrics:Record<string,any>;created_at:string}
type Task={id:string;status:string;progress:number;error?:string;result?:{evaluation_id?:string}}
const datasets=ref<{id:string;name:string}[]>([]),dataset=ref('dsa'),tasks=ref<Task[]>([]),runs=ref<Run[]>([]),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),message=ref(''),selected=ref<string[]>([]),comparison=ref<{comparable:boolean;notice:string;runs:Run[]}|null>(null),detail=ref<Run|null>(null)
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false,requestId=''
const labels:Record<string,string>={recall_at_5:'资料召回率',mrr:'排序质量',refusal_accuracy:'拒答准确率',citation_accuracy:'引用精度',page_recall_at_5:'页码召回率',page_citation_accuracy:'页码精度',latency_p95_ms:'P95耗时',source_coverage:'资料覆盖'}
const states:Record<string,string>={queued:'排队中',processing:'评测中',completed:'已完成',failed:'未完成',cancelled:'已取消'}
const req=<T,>(path:string,body?:unknown)=>accountRequest<T>(props.base,props.token,path,body)
async function load(){if(timer)clearTimeout(timer);try{
  const [t,r]=await Promise.all([req<{items:Task[]}>('/admin/evaluation-tasks?page=1&page_size=6'),req<{items:Run[];total:number}>(`/paged/evaluations?page=${page.value}&page_size=6`)])
  if(disposed)return;tasks.value=t.items;runs.value=r.items;total.value=r.total
  if(tasks.value.some(i=>['queued','processing'].includes(i.status)))timer=setTimeout(()=>void load(),3000)
}catch(e){error.value=e instanceof Error?e.message:'读取失败';if(!disposed)timer=setTimeout(()=>void load(),15000)}}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
function start(){void run(async()=>{requestId ||= crypto.randomUUID();await req('/admin/evaluation-tasks',{request_id:requestId,dataset:dataset.value});requestId='';message.value='任务已进入队列，可离开后再查看。';await load()})}
function cancel(t:Task){void run(async()=>{await req('/admin/evaluation-tasks/'+t.id+'/cancel',{});await load()})}
function compare(){void run(async()=>{comparison.value=await req('/admin/evaluation-compare?ids='+selected.value.join(','))})}
function download(r:Run,format:string){void run(()=>downloadFile(props.base,props.token,`/admin/evaluations/${r.id}/download?format=${format}`))}
onMounted(()=>void run(async()=>{datasets.value=await req('/admin/evaluation-datasets');await load()}))
onBeforeUnmount(()=>{disposed=true;if(timer)clearTimeout(timer)})
</script>
<template><section class="panel evaluation-workbench"><h2>检索质量评测</h2><p class="muted">选择题集后开始检测，查看证据精度、页码定位和拒答表现。</p><div class="eval-controls"><label>评测题集<select v-model="dataset" :disabled="busy" @change="requestId=''"><option v-for="d in datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></label><button :disabled="busy" @click="start">开始评测</button><button class="secondary" :disabled="busy" @click="run(load)">刷新</button></div><p v-if="busy" role="status"><span class="ui-spinner"/>正在处理…</p><p v-if="message" role="status">{{message}}</p><p v-if="error" role="alert">{{error}}</p><div class="eval-tasks"><article v-for="t in tasks" :key="t.id"><div><strong>{{states[t.status]||t.status}}</strong><span v-if="['queued','processing'].includes(t.status)"><span class="ui-spinner"/> {{t.progress}}%</span><small v-if="t.error">{{t.error}}</small></div><button v-if="['queued','processing'].includes(t.status)" class="secondary" :disabled="busy" @click="cancel(t)">取消</button><span v-else-if="t.status==='completed'">{{t.result?.evaluation_id?'报告已保存':''}}</span></article></div>
<div class="eval-heading"><h3>评测报告</h3><button :disabled="busy||selected.length<2||selected.length>3" @click="compare">对比已选（{{selected.length}}）</button></div><article v-for="r in runs" :key="r.id" class="eval-report"><label class="eval-choice"><input v-model="selected" type="checkbox" :value="r.id" :disabled="!selected.includes(r.id)&&selected.length>=3"/>{{r.dataset_version}}</label><small>{{new Date(r.created_at).toLocaleString('zh-CN')}} · {{r.case_count}}题</small><strong :class="r.metrics.gate_details?.passed?'passed':'failed'">{{r.metrics.gate_details ? r.metrics.gate_details.passed?'达到当前门槛':'未达到当前门槛':'历史标准，请重新评测'}}</strong><div class="eval-stats"><span>召回 {{Math.round((r.metrics.recall_at_5||0)*100)}}%</span><span>引用精度 {{Math.round((r.metrics.citation_accuracy||0)*100)}}%</span><span>拒答 {{Math.round((r.metrics.refusal_accuracy||0)*100)}}%</span></div><div class="eval-buttons"><button class="secondary" @click="detail=r">指标详情</button><button class="secondary" :disabled="busy" @click="download(r,'json')">下载报告</button><button class="secondary" :disabled="busy" @click="download(r,'csv')">用例 CSV</button></div></article><p v-if="!runs.length" class="muted">暂无报告，完成首轮评测后显示。</p><nav aria-label="评测报告分页"><span>共{{total}}份 · 第{{page}}页</span><button class="secondary" :disabled="busy||page<=1" @click="page--;run(load)">上一页</button><button class="secondary" :disabled="busy||page*6>=total" @click="page++;run(load)">下一页</button></nav>
<DetailDialog v-if="detail" title="评测指标详情" @close="detail=null"><p>{{detail.dataset_version}}</p><p>{{detail.metrics.gate_details?.policy||'历史标准，未纳入当前门槛'}}</p><dl><template v-for="(name,key) in labels" :key="key"><dt>{{name}}</dt><dd>{{detail.metrics[key]??'—'}} <span v-if="detail.metrics.gate_details?.checks[key]!==undefined">{{detail.metrics.gate_details.checks[key]?'通过':'未通过'}}</span></dd></template></dl><p v-if="detail.metrics.source_coverage">资料覆盖：{{detail.metrics.source_coverage.covered_cases}} / {{detail.metrics.source_coverage.positive_cases}}，缺失{{detail.metrics.source_coverage.missing_cases}}条。</p><ul v-if="detail.metrics.source_coverage?.missing_documents?.length"><li v-for="name in detail.metrics.source_coverage.missing_documents" :key="name">{{name}}</li></ul></DetailDialog>
<DetailDialog v-if="comparison" title="报告对比" @close="comparison=null"><p>{{comparison.notice}}</p><article v-for="r in comparison.runs" :key="r.id" class="eval-report"><strong>{{r.dataset_version}} · {{new Date(r.created_at).toLocaleString('zh-CN')}}</strong><p v-for="(name,key) in labels" :key="key">{{name}}：{{r.metrics[key]??'—'}}</p></article></DetailDialog></section></template>
<style scoped>.evaluation-workbench{min-width:0}.muted,small{color:#71829a;font-size:12px}.eval-controls,.eval-heading,.eval-buttons,nav{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.eval-controls label{display:grid;gap:6px;flex:1;min-width:160px}.eval-heading{justify-content:space-between;margin-top:20px}.eval-report{border:1px solid #dfe7f2;border-radius:14px;padding:14px;margin:10px 0;display:grid;gap:8px}.eval-choice{display:flex;align-items:center;gap:8px;font-weight:650}.eval-choice input{width:18px;height:18px}.eval-stats{display:flex;flex-wrap:wrap;gap:12px;font-size:12px}.eval-tasks article{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid #e5ebf5;font-size:12px}.eval-tasks small{display:block}.eval-tasks span{margin-left:8px}.passed{color:#17785d}.failed{color:#a95b24}nav{margin-top:12px}nav span{margin-right:auto;font-size:12px}button{min-height:38px;font-size:12px}dl{display:grid;grid-template-columns:1fr 1fr;gap:12px}dd{margin:0}@media(max-width:480px){.eval-report{padding:11px}.eval-buttons button{flex:1;white-space:nowrap;padding:7px}.eval-controls select{font-size:12px}}</style>
